import Foundation
import SQLite3

/// Provides a thin, convenience-oriented wrapper around a SQLite connection.
public class Database {
    private let path: String
    private let errorHandler: ((SQLiteError) -> Void)?
    private var sqlite: OpaquePointer? = nil
    
    /// The row ID generated by the most recent successful INSERT statement.
    public var lastInsertRowId: Int { Int(sqlite3_last_insert_rowid(self.sqlite)) }
    
    /// The number of rows modified by the most recent SQL statement.
    public var affectedRows: Int {
        if #available(macOS 12.3, iOS 15.4, *) {
            return Int(sqlite3_changes64(self.sqlite))
        } else {
            return Int(sqlite3_changes(self.sqlite))
        }
    }
    
    /// The version string reported by the linked SQLite library.
    static public var sqliteVersion: String { String(cString: sqlite3_libversion()) }
    
    /// Opens or creates a database at the supplied path and optionally installs an error handler.
    static internal func open(_ path: String, readonly: Bool = false, onError: ((SQLiteError) -> Void)? = nil) throws -> Database {
        let db = Database(path, onError: onError)
        try db.open(readonly: readonly)
        try? db.executeQuery("PRAGMA foreign_keys = ON")
        return db
    }
    
    /// Opens the database, executes a closure, and closes the connection when the block exits.
    static public func open(_ path: String, readonly: Bool = false, execute code: (_ db: Database) throws -> Void) throws {
        let db = try Database.open(path, readonly: readonly)
        defer { db.close() }
        try code(db)
    }
    
    /// Attaches another SQLite database file under the supplied schema name.
    public func attach(databaseAtPath path: String, withSchema schema: String) throws {
        if !checkSchemaAlreadyExists(schema: schema) {
            try executeQuery("ATTACH DATABASE '\(path)' AS \(schema)")
        }
    }
    
    /// Detaches an attached database schema from this connection.
    public func detach(schema: String) throws {
        try executeQuery("DETACH DATABASE \(schema)")
    }
    
    /// Starts an explicit database transaction.
    public func beginTransaction() throws {
        try executeQuery("BEGIN TRANSACTION")
    }
    
    /// Commits the currently open transaction when it exists.
    public func commit() {
        try? executeQuery("COMMIT")
    }
    
    /// Rolls back the current transaction, if any is active.
    public func rollBack() {
        try? executeQuery("ROLLBACK")
    }
    
    /// Executes a closure inside a transaction that rolls back automatically if the block throws.
    public func transaction(execute code: () throws -> Void) throws {
        do {
            try beginTransaction()
            try code()
            commit()
        } catch {
            rollBack()
            #if DEBUG
            print("Transaction rolled back")
            #endif
            throw error
        }
    }
    
    /// Prepares and returns a `Statement` for executing a SQL query.
    public func prepareStatement(_ query: String) throws -> Statement {
        guard let statement = Statement(sqlite: self.sqlite, query: query, onError: self.errorHandler) else {
            throw sqliteError(query: query)
        }
        return statement
    }
    
    /// Compiles a statement and executes a closure with the prepared object.
    public func prepareStatement(_ query: String, execute code: (Statement) throws -> Void) throws {
        let stmt = try prepareStatement(query)
        defer { stmt.finalize() }
        try code(stmt)
    }
    
    /// Executes a SQL statement without returning rows.
    public func executeQuery(_ query: String) throws {
        var error: UnsafeMutablePointer<CChar>?
        if sqlite3_exec(self.sqlite, query, nil, nil, &error) != SQLITE_OK {
            if let error {
                let message = String(cString: error)
                sqlite3_free(error)
                throw sqliteError(message: message, query: query)
            }
        }
    }
    
    /// Executes a parameterized statement using positional arguments.
    public func executeStatement(_ query: String, parameters: [Any?]) throws {
        try prepareStatement(query) { stmt in
            if let parameters = parameters as? [[String: Any?]] {
                for row in parameters {
                    try stmt.bind(parameters: row)
                    try stmt.step()
                    try stmt.reset()
                }
            } else if let parameters = parameters as? [[Any?]] {
                for row in parameters {
                    try stmt.bind(parameters: row)
                    try stmt.step()
                    try stmt.reset()
                }
            } else {
                try stmt.bind(parameters: parameters)
                try stmt.step()
            }
        }
    }
    
    /// Executes a parameterized statement using named arguments.
    public func executeStatement(_ query: String, parameters: [String: Any?]) throws {
        try prepareStatement(query) { stmt in
            try stmt.bind(parameters: parameters)
            try stmt.step()
        }
    }
    
    /// Returns all rows produced by a positional-parameter query.
    public func select(_ query: String, parameters: [Any?] = []) throws -> [[String: Any?]] {
        var result: [[String: Any?]] = []
        try prepareStatement(query) { stmt in
            try stmt.bind(parameters: parameters)
            while let row = stmt.fetch() {
                result.append(row)
            }
        }
        return result
    }
    
    /// Returns all rows produced by a named-parameter query.
    public func select(_ query: String, parameters: [String: Any?]) throws -> [[String: Any?]] {
        var result: [[String: Any?]] = []
        try prepareStatement(query) { stmt in
            try stmt.bind(parameters: parameters)
            while let row = stmt.fetch() {
                result.append(row)
            }
        }
        return result
    }
    
    /// Returns the first row from a positional-parameter query, if one exists.
    public func selectFirst(_ query: String, parameters: [Any?] = []) throws -> [String: Any?]? {
        return try select(query, parameters: parameters).first
    }
    
    /// Returns the first row from a named-parameter query, if one exists.
    public func selectFirst(_ query: String, parameters: [String: Any?]) throws -> [String: Any?]? {
        return try? select(query, parameters: parameters).first
    }
    
    /// Reads a single boolean value from a scalar query.
    public func selectBool(_ query: String, parameters: [Any?] = []) throws -> Bool? {
        var scalar: Bool? = nil
        try prepareStatement(query) { stmt in
            try stmt.bind(parameters: parameters)
            if try stmt.step() {
                scalar = stmt.getBool(forIndex: 0)
            }
        }
        return scalar
    }
    
    /// Reads a single boolean value from a named-parameter scalar query.
    public func selectBool(_ query: String, parameters: [String: Any?]) throws -> Bool? {
        var scalar: Bool? = nil
        try prepareStatement(query) { stmt in
            try stmt.bind(parameters: parameters)
            if try stmt.step() {
                scalar = stmt.getBool(forIndex: 0)
            }
        }
        return scalar
    }
    
    /// Reads a single floating-point value from a scalar query.
    public func selectDouble(_ query: String, parameters: [Any?] = []) throws -> Double? {
        var scalar: Double? = nil
        try prepareStatement(query) { stmt in
            try stmt.bind(parameters: parameters)
            if try stmt.step() {
                scalar = stmt.getDouble(forIndex: 0)
            }
        }
        return scalar
    }
    
    /// Reads a single floating-point value from a named-parameter scalar query.
    public func selectDouble(_ query: String, parameters: [String: Any?]) throws -> Double? {
        var scalar: Double? = nil
        try prepareStatement(query) { stmt in
            try stmt.bind(parameters: parameters)
            if try stmt.step() {
                scalar = stmt.getDouble(forIndex: 0)
            }
        }
        return scalar
    }
    
    /// Reads a single integer value from a scalar query.
    public func selectInt(_ query: String, parameters: [Any?] = []) throws -> Int? {
        var scalar: Int? = nil
        try prepareStatement(query) { stmt in
            try stmt.bind(parameters: parameters)
            if try stmt.step() {
                scalar = stmt.getInt(forIndex: 0)
            }
        }
        return scalar
    }
    
    /// Reads a single integer value from a named-parameter scalar query.
    public func selectInt(_ query: String, parameters: [String: Any?]) throws -> Int? {
        var scalar: Int? = nil
        try prepareStatement(query) { stmt in
            try stmt.bind(parameters: parameters)
            if try stmt.step() {
                scalar = stmt.getInt(forIndex: 0)
            }
        }
        return scalar
    }
    
    /// Reads a single string value from a scalar query.
    public func selectString(_ query: String, parameters: [Any?] = []) throws -> String? {
        var scalar: String? = nil
        try prepareStatement(query) { stmt in
            try stmt.bind(parameters: parameters)
            if try stmt.step() {
                scalar = stmt.getString(forIndex: 0)
            }
        }
        return scalar
    }
    
    /// Reads a single string value from a named-parameter scalar query.
    public func selectString(_ query: String, parameters: [String: Any?]) throws -> String? {
        var scalar: String? = nil
        try prepareStatement(query) { stmt in
            try stmt.bind(parameters: parameters)
            if try stmt.step() {
                scalar = stmt.getString(forIndex: 0)
            }
        }
        return scalar
    }
    
    internal func close() {
        sqlite3_close(self.sqlite)
        self.sqlite = nil
    }
    
    private init(_ path : String, onError: ((SQLiteError) -> Void)? = nil) {
        self.path = path
        self.errorHandler = onError
    }
    
    deinit {
        close()
    }
    
    private func open(readonly: Bool = false) throws {
        let readMode = readonly ? SQLITE_OPEN_READONLY : SQLITE_OPEN_READWRITE
        if sqlite3_open_v2(self.path, &self.sqlite, readMode, nil) != SQLITE_OK {
            close()
            throw sqliteError()
        }
    }
    
    private func checkSchemaAlreadyExists(schema: String) -> Bool {
        let attachements = getAttachements()
        return attachements.contains(where: { $0["name"] as! String == schema })
    }
    
    private func sqliteError(message: String? = nil, query: String? = nil) -> SQLiteError {
        let message = message ?? String(cString: sqlite3_errmsg(self.sqlite))
        let error = SQLiteError(
            code: Int(sqlite3_errcode(self.sqlite)),
            message: message,
            query: query,
        )
        #if DEBUG
        print(error)
        #endif
        self.errorHandler?(error)
        return error
    }
}

// MARK: - PRAGMAS

extension Database {
    
    /// Returns foreign-key violations for the requested schema.
    public func checkForeignKeys(ofSchema schema: String = "main") -> [[String: Any?]] {
        return (try? select("PRAGMA \(schema).foreign_key_check")) ?? []
    }
    
    /// Returns foreign-key violations for a single table in the requested schema.
    public func checkForeignKeys(ofTable table: String, inSchema schema: String = "main") -> [[String: Any?]] {
        return (try? select("PRAGMA \(schema).foreign_key_check(\(table))")) ?? []
    }
    
    /// Runs the schema integrity check and returns the first rows of the report.
    public func checkIntegrity(ofSchema schema: String = "main", limit: Int = 100, quick: Bool = false) -> [[String: Any?]] {
        if quick {
            return (try? select("PRAGMA \(schema).quick_check(\(limit))")) ?? []
        } else {
            return (try? select("PRAGMA \(schema).integrity_check(\(limit))")) ?? []
        }
    }
    
    /// Runs the integrity check for a table and returns any reported issues.
    public func checkIntegrity(ofTable table: String, inSchema schema: String = "main", quick: Bool = false) -> [[String: Any?]] {
        if quick {
            return (try? select("PRAGMA \(schema).quick_check(\(table))")) ?? []
        } else {
            return (try? select("PRAGMA \(schema).integrity_check(\(table))")) ?? []
        }
    }
    
    /// Runs SQLite optimization pragmas for the schema and optional mask.
    @discardableResult
    public func optimize(schema: String = "main", withMask mask: Int? = nil) -> [[String: Any?]] {
        return (try? select("PRAGMA \(schema).optimize\(mask != nil ? "(\(mask!))" : "")")) ?? []
    }
    
    /// Returns metadata for all attached databases in the current connection.
    public func getAttachements() -> [[String: Any?]] {
        return (try? select("PRAGMA database_list")) ?? []
    }
    
    /// Returns the foreign-key metadata for a table.
    public func getForeignKeys(ofTable table: String) -> [[String: Any?]] {
        return (try? select("PRAGMA foreign_key_list(\(table))")) ?? []
    }
    
    /// Returns the index list for a table in the requested schema.
    public func getIndexes(ofTable table: String, inSchema schema: String = "main") -> [[String: Any?]] {
        return (try? select("PRAGMA \(schema).index_list(\(table))")) ?? []
    }
    
    /// Returns index metadata for the named index in the selected schema.
    public func getInfo(ofIndex index: String, inSchema schema: String = "main")-> [[String: Any?]] {
        return (try? select("PRAGMA \(schema).index_info(\(index))")) ?? []
    }
    
    /// Returns the table schema information gathered from the SQLite table_xinfo pragma.
    public func getInfo(ofTable table: String, inSchema schema: String = "main")-> [[String: Any?]] {
        return (try? select("PRAGMA \(schema).table_xinfo(\(table))")) ?? []
    }
    
    /// Lists tables visible in the requested schema.
    public func getTables(ofSchema schema: String = "main") -> [[String: Any?]] {
        return (try? select("PRAGMA \(schema).table_list")) ?? []
    }
    
    /// Returns the user-defined version value stored for the corresponding schema.
    public func getUserVersion(ofSchema schema: String = "main") -> Int {
        return (try? selectInt("PRAGMA \(schema).user_version")) ?? 0
    }
    
    /// Sets the user-defined version value stored for the schema.
    public func setUserVersion(_ version: Int, ofSchema schema: String = "main") {
        try? executeQuery("PRAGMA \(schema).user_version=\(version)")
    }
}
